def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not twos:
        return [row[:] for row in grid]

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != 2]
    if not points:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    horizontal_divider = len({r for r, c in twos}) == 1

    if horizontal_divider:
        line = twos[0][0]
        minr = min(r for r, c in points)
        maxr = max(r for r, c in points)
        if maxr < line:
            dr = line - 1 - maxr
            marker = minr + dr - 1
        else:
            dr = line + 1 - minr
            marker = maxr + dr + 1
        dc = 0
    else:
        line = twos[0][1]
        minc = min(c for r, c in points)
        maxc = max(c for r, c in points)
        if maxc < line:
            dc = line - 1 - maxc
            marker = minc + dc - 1
        else:
            dc = line + 1 - minc
            marker = maxc + dc + 1
        dr = 0

    for r, c in points:
        out[r][c] = bg
    for r, c in points:
        out[r + dr][c + dc] = grid[r][c]

    if horizontal_divider:
        if 0 <= marker < h:
            for c in range(w):
                out[marker][c] = 8
    else:
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8

    return out
